func (this *CCombo) PopupEvent(eventLike EventLike) {
	var event *Event
	if eventLike != nil {
		event = eventLike.AsEvent()
	}
	_ = event
	switch event.Type {
	case Paint:
		var listRect *Rectangle = this.list.impl.getBounds_()
		var black *Color = this.GetDisplay().impl.getSystemColor_(COLOR_BLACK)
		event.Gc.SetForeground(black)
		event.Gc.DrawRectangle(0, 0, listRect.Width+1, listRect.Height+1)
		break
	case Close:
		event.Doit = false
		this.DropDown(false)
		break
	}
}

